def countBeautiful(s, k):
    m = 4 * k
    L = 1
    p = 2
    while p * p <= m:
        if m % p == 0:
            e = 0
            while m % p == 0:
                m //= p
                e += 1
            L *= p ** ((e + 1) // 2)
        p += 1
    if m > 1:
        L *= m
    cnt = {(0, 0): 1}
    bal = 0
    total = 0
    for i, ch in enumerate(s, 1):
        bal += 1 if ch in "aeiou" else -1
        key = (bal, i % L)
        total += cnt.get(key, 0)
        cnt[key] = cnt.get(key, 0) + 1
    return total
